/* 
  Valid JSON vs Invalid JSON 
*/

// ❌ INVALID JSON (Keys lack quotes, uses single quotes, trailing comma)
{
  name: 'John',
  age: 30,
}

// ✅ VALID JSON (Strict double quotes on keys and strings, no trailing commas)
{
  "name": "John",
  "age": 30,
  "isAdmin": false,
  "hobbies": ["reading", "gaming"],
  "address": {
    "city": "New York"
  },
  "spouse": null
}

// Translating between JS and JSON
const jsObject = { a: 1 };
const jsonString = JSON.stringify(jsObject); // Turns into text for the network
const backToObject = JSON.parse(jsonString); // Turns back into JS object
